#!/bin/zsh
# Rebuild ClickCast.app from source. No Xcode required (Command Line Tools only).
set -e
cd "$(dirname "$0")"
VERSION=$(cat VERSION)
BUILT=$(date "+%b %d, %H:%M")
cat > Sources/ClickCast/Version.swift <<SWIFT
// Generated by build.sh — do not edit.
enum AppVersion {
    static let version = "$VERSION"
    static let built = "$BUILT"
}
SWIFT
CACHE="${TMPDIR:-/tmp}/clickcast-modcache"
mkdir -p "$CACHE"
mkdir -p ClickCast.app/Contents/MacOS ClickCast.app/Contents/Resources
swiftc -O -module-cache-path "$CACHE" -o ClickCast.app/Contents/MacOS/ClickCast Sources/ClickCast/*.swift
/usr/libexec/PlistBuddy -c "Set :CFBundleShortVersionString $VERSION" ClickCast.app/Contents/Info.plist 2>/dev/null || true
codesign --force --sign - ClickCast.app
echo "Built ClickCast.app v$VERSION ($BUILT)"
